Here's a Go program that parses a struct in a Go source file and generates an Avro schema from it:

```go
package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/apache/avro/v10/schema"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run parse_struct.go <go_source_file> <struct_name>")
		os.Exit(1)
	}

	goSourceFile := os.Args[1]
	structName := os.Args[2]

	content, err := os.ReadFile(goSourceFile)
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}

	// Extract the struct definition from the Go source file
	structDef := extractStructDef(string(content))
	if structDef == "" {
		fmt.Println("Unable to extract struct definition")
		os.Exit(1)
	}

	// Generate the Avro schema
	avroSchema, err := generateAvroSchema(structDef)
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}

	// Write the Avro schema to a file
	err = os.WriteFile("struct.avsc", []byte(avroSchema), 0644)
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}
}

func extractStructDef(goSourceCode string) string {
	// Regular expression pattern to match struct definitions
	pattern := `type (\w+) struct {`

	// Split the Go source code into lines
	lines := strings.Split(goSourceCode, "\n")

	// Iterate through the lines and find the struct definition
	for _, line := range lines {
		match := strings.Match(line, pattern)
		if match {
			return line[len(pattern):]
		}
	}

